long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops,
                    const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    long ret;
    int i;

    if (nsops == 0)
        return -EINVAL;

    sops = kmalloc(nsops * sizeof(struct oabi_sembuf), GFP_KERNEL);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(struct oabi_sembuf))) {
        kfree(sops);
        return -EFAULT;
    }

    for (i = 0; i < (int)nsops; i++) {
        if (sops[i].sem_num >= seminfo.semmni ||
            sops[i].sem_op < 0) {
            kfree(sops);
            return -EINVAL;
        }
    }

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to))) {
            kfree(sops);
            return -EFAULT;
        }
        ret = do_semtimedop(semid, sops, nsops, &to);
    } else {
        ret = do_semtimedop(semid, sops, nsops, NULL);
    }

    kfree(sops);
    return ret;
}

